def pseudo_moves(bd, white):
    moves=[]
    for i,p in enumerate(bd):
        if p=='.': continue
        if white and p.islower(): continue
        r,c=i//8,i%8
        low=p.lower()
        if low=='p':
            dir_=-1 if white else 1
            start=1 if white else 6
            promo=7 if white else 0
            one=i+dir_
            if 0<=one<64 and bd[one]=='.':
                rr=rank_of(one)
                if rr==promo:
                    for pr in ['q','r','b','n']:
                        moves.append((i,one,pr))
                else:
                    moves.append((i,one))
                    two=one+dir_
                    if r==start and 0<=two<64 and bd[two]=='.':
                        moves.append((i,two))
            for dc in [-1,1]:
                nc=c+dc; nt=one+dc
                if 0<=nt<64 and bd[nt]!='.':
                    tgt=bd[nt]
                    if (white and tgt.isupper()) or (not white and tgt.islower()):
                        rr=rank_of(nt)
                        if rr==promo:
                            for pr in ['q','r','b','n']:
                                moves.append((i,nt,pr))
                        else:
                            moves.append((i,nt))

